use super::*;

/// How tightly receipts cluster on the median, as a 0-1 score.
pub(crate) fn consistency_of(amounts: &[i64]) -> f64 {
    let mid = median(amounts);
    if mid == 0 {
        return 0.0;
    }
    let spread = amounts.iter().map(|v| (v - mid).abs() as f64).sum::<f64>() / amounts.len() as f64;
    (1.0 - spread / mid as f64).clamp(0.0, 1.0)
}
